  ('In the NBA, how many personal fouls disqualify a player from a game?', array['4','5','6','7'], 2, 'medium'),
  ('How many Grand Slam tennis tournaments are held each year?', array['3','4','5','6'], 1, 'easy'),
  ('Which Grand Slam tennis tournament is played on clay courts?', array['Wimbledon','US Open','French Open','Australian Open'], 2, 'easy'),
  ('Which Grand Slam tennis tournament is held in Melbourne?', array['Australian Open','US Open','French Open','Wimbledon'], 0, 'easy'),
  ('In tennis, what is a score of 40-40 called?', array['Deuce','Love','Advantage','Break'], 0, 'easy'),
