  ('In golf, what is the term for finishing a hole one stroke over par?', array['Eagle','Birdie','Bogey','Albatross'], 2, 'easy'),
  ('In golf, what is the term for finishing a hole two strokes under par?', array['Eagle','Birdie','Condor','Albatross'], 0, 'medium'),
  ('Which major golf championship is played annually at Augusta National?', array['The Masters','The Open Championship','The US Open','The PGA Championship'], 0, 'medium'),
  ('Which golfer holds the record for the most men''s major championships won?', array['Tiger Woods','Jack Nicklaus','Arnold Palmer','Gary Player'], 1, 'medium'),
  ('How many clubs is a golfer allowed to carry in their bag during a round?', array['10','12','14','16'], 2, 'medium'),
