  ('Which heavyweight boxer was known as "Iron Mike"?', array['Mike Tyson','George Foreman','Sugar Ray Leonard','Evander Holyfield'], 0, 'easy'),
  ('What is the heaviest weight division in professional boxing called?', array['Middleweight','Heavyweight','Cruiserweight','Welterweight'], 1, 'easy'),
