  ('How often are the Winter Olympic Games held?', array['Every 2 years','Every 4 years','Every 5 years','Every 6 years'], 1, 'easy'),
  ('Which city hosted the 2020 Summer Olympics, actually held in 2021?', array['Tokyo','Beijing','Paris','London'], 0, 'easy'),
