  ('How many innings are in a standard Major League Baseball game?', array['7','8','9','10'], 2, 'easy'),
  ('How many players from one team are on the field at once in baseball?', array['8','9','10','11'], 1, 'easy'),
  ('How many strikes result in a batter being called out in baseball?', array['2','3','4','5'], 1, 'easy'),
  ('What is it called when a batter hits a home run with the bases loaded, scoring four runs?', array['A grand slam','A home run derby','A triple play','A perfect game'], 0, 'medium'),
  ('How many players from one team are on the field at once in American football?', array['9','10','11','12'], 2, 'easy'),
  ('What is it called when a quarterback throws the ball into the ground to stop the clock?', array['A spike','A sack','A punt','A fumble'], 0, 'medium'),
  ('How many career Super Bowl wins does quarterback Tom Brady have?', array['5','6','7','8'], 2, 'medium'),
  ('In American football, what is a successful kick through the goalposts worth 3 points called?', array['A field goal','A touchdown','A safety','A two-point conversion'], 0, 'easy'),
