  ('What colour jersey does the overall leader wear in the Tour de France?', array['Yellow','Green','Polka dot','White'], 0, 'easy'),
  ('In the Tour de France, what does the green jersey represent?', array['Best climber','Points classification','Best young rider','Overall leader'], 1, 'medium'),
  ('Which sport uses terms like "spare" and "strike"?', array['Ten-pin bowling','Darts','Snooker','Table tennis'], 0, 'easy'),
  ('In snooker, how many red balls are on the table at the start of a frame?', array['10','12','15','20'], 2, 'medium'),
  ('In darts, what is the highest score achievable with a single dart?', array['50','57','60','180'], 2, 'medium'),
  ('What is it called when a player finishes a leg of darts by reducing their score to exactly zero?', array['A finish','A bullseye','A maximum','A ton'], 0, 'medium'),
  ('Which trophy is awarded to the NHL playoff champion in ice hockey?', array['The Stanley Cup','The Vince Lombardi Trophy','The Commissioner''s Trophy','The Larry O''Brien Trophy'], 0, 'easy')
